#ifndef HB_CPUID_H
#define HB_CPUID_H

/* MacRunner 2026-08-12, лейн ЛЕСТНИЦА, итерация 761 — ЕДИНСТВЕННОЕ ОПИСАНИЕ CPUID.
 *
 * Ответ на CPUID жил ДВУМЯ копиями: `hb_interpreter.c` (HB_IR_CPUID) и
 * `hb_arm64_codegen.c` (`hb_jit_helper_cpuid`). Правка одной копии давала гостю разную
 * личность процессора в зависимости от того, кто исполнил команду, — так уже случилось
 * дважды (итерации 531 и 584, оба раза чинили постфактум). Здесь копия одна, оба
 * исполнителя зовут её; расходиться нечему.
 *
 * Входящее 104 (ответ на В5): лист 13 обязан быть заполнен ДО подъёма максимального
 * номера листа. Мы объявляем XSAVE=1, OSXSAVE=1 и XCR0=0x7, то есть обещаем сохранение
 * состояния YMM; пустой лист 13 отвечал бы «размер области сохранения = 0», и гость либо
 * выделил бы ноль и испортил память, либо решил бы, что расширенного состояния нет. Это
 * та же семья, что MMX в 302: объявляем то, чего не описываем.
 */

#include "hb_context.h"
#include <stdint.h>
#include <stdlib.h>

/* Разметка области XSAVE (SDM, том 1, гл. 13). Легаси-область FXSAVE 512 байт,
 * заголовок XSAVE 64 байта, дальше компоненты. Компонента 2 (YMM_Hi128) — 256 байт
 * со смещения 576. Итог для XCR0=0x7: 512 + 64 + 256 = 832. */
#define HB_XSAVE_LEGACY_SIZE 512u
#define HB_XSAVE_HEADER_SIZE 64u
#define HB_XSAVE_YMM_OFFSET  (HB_XSAVE_LEGACY_SIZE + HB_XSAVE_HEADER_SIZE) /* 576 */
#define HB_XSAVE_YMM_SIZE    256u
#define HB_XSAVE_AREA_SIZE   (HB_XSAVE_YMM_OFFSET + HB_XSAVE_YMM_SIZE)     /* 832 */

/* Максимальный номер основного листа — ОДИН на оба режима.
 *
 * Здесь стояло 13 для 64 бит и 7 для 32, и это было неверно по сути: `cpuid` описывает
 * ЖЕЛЕЗО, а разрядность режима — свойство исполняемого кода, не процессора. Один и тот же
 * ЦП отвечал по-разному в зависимости от того, кто спросил, — та же болезнь, что лечили в
 * 531 и 584, только в другом месте.
 *
 * Граница проходит иначе: от режима зависят ПРИЗНАКИ (лист 1 — что гость станет исполнять,
 * а VEX и XSAVE в 32 битах у нас не разбираются), но НЕ описание состояния. Лист 13
 * рассказывает про области сохранения и без признака XSAVE не является приглашением
 * что-либо исполнять — гость обязан сперва спросить XSAVE/OSXSAVE в листе 1.
 *
 * Листы 2, 4, 6 оставлены нулями ОСОЗНАННО (решение записано на доску, входящее 104):
 * топология кэша и управление питанием на правильность исполнения не влияют. */
#define HB_CPUID_MAX_LEAF 13u

static inline void hb_cpuid_query(const hb_context_t* ctx, uint32_t leaf, uint32_t subleaf,
                                  uint32_t* out_eax, uint32_t* out_ebx,
                                  uint32_t* out_ecx, uint32_t* out_edx) {
    uint32_t eax = 0, ebx = 0, ecx = 0, edx = 0;
    const int is32 = (ctx && ctx->mode == HB_MODE_32BIT);
    const uint32_t max_leaf = HB_CPUID_MAX_LEAF;

    /* Входящее 104, ответ на В5: лист выше максимального базового обязан отвечать значениями
     * САМОГО ВЫСОКОГО базового листа (SDM, том 2A, CPUID). Мы отвечали нулями, и гость,
     * спросивший несуществующий лист, получал «признака нет» вместо штатного ответа.
     * Граница — 0x8000_0000: выше начинается диапазон РАСШИРЕННЫХ листов со своим
     * максимумом, его мы не описываем и честно отвечаем нулями. Диапазон 0x4000_0000+
     * отведён под гипервизор; мы себя гипервизором не объявляем, поэтому на железе без
     * гипервизора он ведёт себя как переполнение базового — так же поступаем и мы.
     * (Замер: гость спрашивал лист 0x70001000, то есть проверка попадает именно сюда.) */
    if (leaf > max_leaf && leaf < 0x80000000U) leaf = max_leaf;

    switch (leaf) {
        case 0:
            eax = HB_CPUID_MAX_LEAF;
            ebx = 0x756e6547U; /* "Genu" */
            edx = 0x49656e69U; /* "ineI" */
            ecx = 0x6c65746eU; /* "ntel" */
            break;

        case 1:
            eax = 0x000306a9U;
            /* Объявляем только те семейства, у которых есть исполнение и случаи в наборе.
             * SHA/GFNI/AVX-512 в листе 7 не объявляем — гость уйдёт своим запасным путём. */
            ecx = (1U << 0)  |  /* SSE3 */
                  (1U << 1)  |  /* PCLMULQDQ */
                  (1U << 9)  |  /* SSSE3 */
                  (1U << 12) |  /* FMA */
                  (1U << 19) |  /* SSE4.1 */
                  (1U << 20) |  /* SSE4.2 */
                  (1U << 23) |  /* POPCNT */
                  (1U << 25) |  /* AES */
                  (1U << 26) |  /* XSAVE */
                  (1U << 27) |  /* OSXSAVE */
                  (1U << 28) |  /* AVX */
                  (1U << 29);   /* F16C */
            edx = (1U << 8)  |  /* CX8 */
                  (1U << 15) |  /* CMOV */
                  (1U << 24) |  /* FXSR */
                  (1U << 25) |  /* SSE */
                  (1U << 26);   /* SSE2 */
            /* Итерация 302 — MMX НЕ ОБЪЯВЛЯЕМ: регистров `mm` в состоянии нет, гость на
             * `0F 6F 06` (MOVQ mm0,[esi]) упирался в UNSUPPORTED_OPCODE. Вернуть признак
             * для проверки пути: `MACRUNNER_HB_CPUID_MMX=1`. */
            {
                const char* mmx = getenv("MACRUNNER_HB_CPUID_MMX");
                if (mmx && mmx[0] == '1') edx |= (1U << 23);
            }
            /* Итерации 510 и 584 — В 32 БИТАХ VEX НЕТ, XSAVE НЕ РАЗБИРАЕТСЯ.
             * Замер: AVX (vaddps), FMA (vfmadd132ps), F16C (vcvtph2ps), xsave, xrstor —
             * все UNSUPPORTED_OPCODE в режиме x86. Объявление снимаем ровно в 32 битах. */
            if (is32)
                ecx &= ~((1U << 12) | (1U << 26) | (1U << 27) | (1U << 28) | (1U << 29));
            break;

        case 13: /* 0x0D — состав и размер области XSAVE */
            switch (subleaf) {
                case 0:
                    /* EAX/EDX — какие компоненты состояния поддержаны ПРОЦЕССОРОМ:
                     * x87(0) + SSE(1) + YMM_Hi128(2) = 0x7. Это свойство железа, от
                     * режима не зависит.
                     * EBX — размер области для компонент, ВКЛЮЧЁННЫХ сейчас в XCR0, то
                     * есть ровно то, что отдаёт XGETBV: в 32 битах 0x3 (x87+SSE) → 576,
                     * в 64 битах 0x7 (плюс YMM) → 832. Согласованность XCR0 ↔ размер
                     * области — то самое условие из входящего 104.
                     * ECX — максимум для ВСЕХ поддержанных компонент, всегда 832. */
                    eax = 0x7U;
                    ebx = is32 ? (HB_XSAVE_LEGACY_SIZE + HB_XSAVE_HEADER_SIZE)
                               : HB_XSAVE_AREA_SIZE;
                    ecx = HB_XSAVE_AREA_SIZE;
                    edx = 0;
                    break;
                case 1:
                    /* XSAVEOPT(0), XSAVEC(1), XGETBV с ecx=1 (2), XSAVES(3) — ничего из
                     * этого не реализовано, объявлять нечего. */
                    eax = 0; ebx = 0; ecx = 0; edx = 0;
                    break;
                case 2:
                    /* Компонента YMM_Hi128: размер и смещение от начала области. */
                    eax = HB_XSAVE_YMM_SIZE;
                    ebx = HB_XSAVE_YMM_OFFSET;
                    ecx = 0; /* бит 0 = 0: компонента пользовательского состояния (XCR0) */
                    edx = 0;
                    break;
                default:
                    break; /* прочих компонент нет */
            }
            break;

        default:
            break;
    }

    if (out_eax) *out_eax = eax;
    if (out_ebx) *out_ebx = ebx;
    if (out_ecx) *out_ecx = ecx;
    if (out_edx) *out_edx = edx;
}

/* XCR0 — то же самое значение, что объявляет лист 13, подлеaф 0. Держим рядом,
 * чтобы согласованность нельзя было нарушить правкой в одном месте. */
static inline uint64_t hb_xcr0_value(const hb_context_t* ctx, uint32_t ecx) {
    if (ecx != 0) return 0;
    return (ctx && ctx->mode == HB_MODE_32BIT) ? 0x3ULL : 0x7ULL;
}

#endif /* HB_CPUID_H */
